#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES — 生产 RC 验收（只读检查；不修改生产）
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10
ENV_FILE="${RC_ENV_FILE:-deploy/.env.acceptance}"
RESULT_FILE="${RESULT_FILE:-deploy/rc-acceptance-results.md}"
SSH_OPTS=(-o ConnectTimeout=10 -o BatchMode=yes)

mkdir -p "$(dirname "$RESULT_FILE")"
printf '\n## RC 验收 %s\n\n' "$(date '+%F %T')" >> "$RESULT_FILE"

record() { printf -- '- %s — %s\n' "$1" "$2" >> "$RESULT_FILE"; }

expect_code() {
  local label="$1" expected="$2" url="$3" code
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 "$url" 2>/dev/null || true)
  if [[ "$code" == "$expected" ]]; then
    say "  ${GREEN}✓${RESET} $label ($code)"
    record "$label" "PASS ($code)"
  else
    warn "$label 期望 $expected，实际 ${code:-无响应}"
    record "$label" "FAIL (期望 $expected，实际 ${code:-无响应})"
  fi
}

check_headers() {
  local fqdn="$1" hdrs="$2" label="$3" pattern="$4"
  if printf '%s' "$hdrs" | grep -qiE "^${pattern}:"; then
    say "  ${GREEN}✓${RESET} $label"
    record "$fqdn $label" "PASS"
  else
    warn "$fqdn 缺少 $label"
    record "$fqdn $label" "FAIL"
  fi
}

banner "云河FC 生产 RC 验收"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "环境信息"
say "采集 RC 访问信息。密码不写入文件，后续阶段按需隐藏输入。"
ask RC_DOMAIN "生产域名（不含 www，例如 example.com）："
ask ECS_SSH "ECS SSH 目标（user@host）："
ask RDS_HOST "RDS 主机（私网域名）："
ask RDS_PORT "RDS 端口 [3306]："
RDS_PORT="${RDS_PORT:-3306}"
ask RDS_MIGRATION_USER "迁移账号："
ask RDS_APP_USER "应用账号："
ask ACR_REGISTRY "ACR 仓库地址（仅记录）："
write_env RC_DOMAIN "$RC_DOMAIN"
write_env ECS_SSH "$ECS_SSH"
write_env RDS_HOST "$RDS_HOST"
write_env RDS_PORT "$RDS_PORT"
write_env RDS_MIGRATION_USER "$RDS_MIGRATION_USER"
write_env RDS_APP_USER "$RDS_APP_USER"
write_env ACR_REGISTRY "$ACR_REGISTRY"
chmod 600 "$ENV_FILE"

WEB="https://www.$RC_DOMAIN"
ADMIN="https://admin.$RC_DOMAIN"
API="https://api.$RC_DOMAIN"

open_url "$WEB"
pause "确认 www 首页可正常打开后回车"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "§5.3 部署冒烟"
health=$(curl -fsS --max-time 10 "$API/actuator/health" 2>/dev/null || true)
if [[ "$health" == *'"status":"UP"'* ]]; then
  say "  ${GREEN}✓${RESET} readiness $API/actuator/health = UP"; record "§5.3 health UP" "PASS"
else
  warn "$API/actuator/health 未返回 UP"; record "§5.3 health UP" "FAIL"
fi
expect_code "C 端首页 200" "200" "$WEB/"
expect_code "公开读接口 200" "200" "$WEB/api/v1/c/matches?scope=upcoming&page=1&pageSize=1"
expect_code "api 子域公开读 200" "200" "$API/api/v1/c/matches?scope=upcoming&page=1&pageSize=1"
expect_code "api 子域根路径 404" "404" "$API/"
expect_code "api 子域 /admin 404" "404" "$API/admin/"
expect_code "api 子域 health 200" "200" "$API/actuator/health"
wechat_code=$(curl -s -o /dev/null -w '%{http_code}' -H 'Accept: text/html' --max-time 10 "$WEB/api/v1/c/auth/wechat/callback" 2>/dev/null || true)
if [[ "$wechat_code" == "302" ]]; then
  say "  ${GREEN}✓${RESET} 微信回调 HTML 导航 302"; record "§5.3 微信回调 302" "PASS"
else
  warn "微信回调期望 302，实际 ${wechat_code:-无响应}"; record "§5.3 微信回调 302" "FAIL"
fi
open_url "$ADMIN/"
if confirm "www 与 admin 同源登录成功、无重定向循环？"; then
  record "§5.3 www/admin 同源登录" "PASS"
else
  record "§5.3 www/admin 同源登录" "FAIL"
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "§6.1 TLS / 证书"
for host in www admin api; do
  fqdn="$host.$RC_DOMAIN"
  if echo | openssl s_client -servername "$fqdn" -connect "$fqdn:443" 2>/dev/null \
      | openssl x509 -checkend 2592000 -noout >/dev/null 2>&1; then
    say "  ${GREEN}✓${RESET} $fqdn 证书剩余 >30 天"; record "$fqdn 证书>30天" "PASS"
  else
    warn "$fqdn 证书缺失或剩余 ≤30 天"; record "$fqdn 证书>30天" "FAIL"
  fi
  for v in tls1_2 tls1_3; do
    if echo | openssl s_client -"$v" -servername "$fqdn" -connect "$fqdn:443" >/dev/null 2>&1; then
      say "  ${GREEN}✓${RESET} $fqdn 支持 ${v#tls}"
      record "$fqdn 支持 ${v#tls}" "PASS"
    else
      warn "$fqdn 未协商 ${v#tls}"; record "$fqdn 支持 ${v#tls}" "FAIL"
    fi
  done
  redirect=$(curl -sI --max-time 10 "http://$fqdn/" 2>/dev/null | head -n1 || true)
  if [[ "$redirect" == *"301"* || "$redirect" == *"308"* ]]; then
    say "  ${GREEN}✓${RESET} $fqdn 80 → 301/308"; record "$fqdn HTTP→HTTPS" "PASS"
  else
    warn "$fqdn 80 端口未重定向：${redirect:-无响应}"; record "$fqdn HTTP→HTTPS" "FAIL"
  fi
done

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "§6.2 安全响应头"
for fqdn in "www.$RC_DOMAIN" "admin.$RC_DOMAIN"; do
  hdrs=$(curl -sI --max-time 10 "https://$fqdn/" 2>/dev/null || true)
  check_headers "$fqdn" "$hdrs" "HSTS" "strict-transport-security"
  check_headers "$fqdn" "$hdrs" "X-Content-Type-Options" "x-content-type-options"
  check_headers "$fqdn" "$hdrs" "Referrer-Policy" "referrer-policy"
  check_headers "$fqdn" "$hdrs" "X-Frame-Options" "x-frame-options"
  check_headers "$fqdn" "$hdrs" "Permissions-Policy" "permissions-policy"
  if printf '%s' "$hdrs" | grep -qiE '^content-security-policy:'; then
    warn "$fqdn 出现 CSP（设计要求无 CSP）"; record "$fqdn 无 CSP" "FAIL"
  else
    say "  ${GREEN}✓${RESET} $fqdn 无 CSP"; record "$fqdn 无 CSP" "PASS"
  fi
done

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "§6.3 Cookie 与会话"
say "在浏览器登录 admin，DevTools → Application → Cookies 检查会话 Cookie。"
open_url "$ADMIN/"
step "Secure=true；HttpOnly=true；SameSite=Lax；Domain 为空；Path=/。"
if confirm "Cookie 属性全部符合？"; then
  record "§6.3 Cookie 属性" "PASS"
else
  record "§6.3 Cookie 属性" "FAIL"
fi
unauth_code=$(curl -s -o /dev/null -w '%{http_code}' -X POST --max-time 10 \
  -H 'Content-Type: application/json' -d '{}' "$WEB/api/v1/c/registrations" 2>/dev/null || true)
if [[ "$unauth_code" == "401" ]]; then
  say "  ${GREEN}✓${RESET} 未登录写接口 401"; record "§6.3 未登录写接口" "PASS"
else
  warn "未登录写接口期望 401，实际 ${unauth_code:-无响应}"; record "§6.3 未登录写接口" "FAIL"
fi

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "§6.4 CORS"
for origin in "$WEB" "$ADMIN"; do
  allow=$(curl -s -D - -o /dev/null -X OPTIONS --max-time 10 \
    -H "Origin: $origin" -H 'Access-Control-Request-Method: GET' \
    "$API/api/v1/c/matches?scope=upcoming&page=1&pageSize=1" 2>/dev/null \
    | grep -i '^access-control-allow-origin:' || true)
  if [[ "$allow" == *"$origin"* ]]; then
    say "  ${GREEN}✓${RESET} $origin 预检通过"; record "§6.4 CORS $origin" "PASS"
  else
    warn "$origin 预检未返回 ACAO"; record "§6.4 CORS $origin" "FAIL"
  fi
done
evil=$(curl -s -D - -o /dev/null -X OPTIONS --max-time 10 \
  -H 'Origin: https://evil.example' -H 'Access-Control-Request-Method: GET' \
  "$API/api/v1/c/matches?scope=upcoming&page=1&pageSize=1" 2>/dev/null \
  | grep -i '^access-control-allow-origin:' || true)
if [[ -z "$evil" ]]; then
  say "  ${GREEN}✓${RESET} 非白名单 Origin 无 ACAO"; record "§6.4 CORS 非白名单" "PASS"
else
  warn "非白名单 Origin 返回 ACAO：$evil"; record "§6.4 CORS 非白名单" "FAIL"
fi

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "§6.5 真实 IP / §6.8 Redis 与 Kafka"
say "以下为 ECS 只读检查；SSH 不可用时手工执行并确认。"
listeners=$(ssh "${SSH_OPTS[@]}" "$ECS_SSH" "ss -lntp | grep -E ':(6379|9092|8080)\b' || true" 2>/dev/null || true)
printf '%s\n' "${listeners:-（无输出）}"
if confirm "6379/9092/8080 均未对公网监听（仅 127.0.0.1 或容器网络）？"; then
  record "§6.8 端口未对公网发布" "PASS"
else
  record "§6.8 端口未对公网发布" "FAIL"
fi
say "未认证 Redis ping 应失败："
ssh "${SSH_OPTS[@]}" "$ECS_SSH" "docker exec \$(docker ps -qf name=redis | head -n1) redis-cli ping" 2>/dev/null || true
if confirm "未认证 Redis ping 被拒绝，且应用带密码连接正常？"; then
  record "§6.8 Redis 认证" "PASS"
else
  record "§6.8 Redis 认证" "FAIL"
fi
step "登录一次后用 grep 查 nginx access log 与审计 client IP。"
step "伪造 X-Forwarded-For 再请求一次，确认日志/审计仍是真实 IP。"
if confirm "伪造 XFF 未生效，backend 公网不可达？"; then
  record "§6.5 真实 IP" "PASS"
else
  record "§6.5 真实 IP" "FAIL"
fi

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "§6.6 暴露面 / §6.7 迁移与账号"
for base in "$WEB" "$API"; do
  for path in /actuator/env /actuator/beans /v3/api-docs /swagger-ui/index.html; do
    expect_code "敏感端点 $base$path 404" "404" "$base$path"
  done
done
say "在 ECS 上执行 flyway info（密码用占位符，手工替换；不要写进脚本）："
note "docker run --rm --network host -v /opt/yunhefc/migrations:/flyway/sql:ro flyway/flyway:11.7.2 -url='jdbc:mysql://$RDS_HOST:$RDS_PORT/yunhefc?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC&characterEncoding=utf8' -user=$RDS_MIGRATION_USER -password='<迁移账号密码>' info"
if confirm "flyway info 无 pending/failed，flyway_schema_history 为 V1–V5？"; then
  record "§5.1/§6.7 flyway info" "PASS"
else
  record "§5.1/§6.7 flyway info" "FAIL"
fi
say "应用账号权限检查（在 ECS 上执行）："
note "mysql -h $RDS_HOST -P $RDS_PORT -u $RDS_APP_USER -p -e 'SHOW GRANTS FOR CURRENT_USER();'"
step "应只看到 SELECT/INSERT/UPDATE/DELETE，无 CREATE/ALTER/DROP/INDEX。"
if confirm "应用账号无 DDL 权限？"; then
  record "§6.7 应用账号无 DDL" "PASS"
else
  record "§6.7 应用账号无 DDL" "FAIL"
fi
backend_env=$(ssh "${SSH_OPTS[@]}" "$ECS_SSH" "docker inspect -f '{{range .Config.Env}}{{println .}}{{end}}' \$(docker ps -qf name=backend | head -n1)" 2>/dev/null || true)
if printf '%s' "$backend_env" | grep -q '^SPRING_PROFILES_ACTIVE=prod$'; then
  say "  ${GREEN}✓${RESET} 后端以 prod profile 运行（application-prod.yml 关闭 Flyway）"; record "§5.1 flyway.enabled=false" "PASS"
else
  warn "未确认后端以 prod profile 运行"; record "§5.1 flyway.enabled=false" "FAIL"
fi

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "§6.9 限流与锁定 / §6.10 日志与密钥"
ask TEST_PHONE "专用测试手机号（仅用于限流验证）："
say "将连续发起 11 次错误登录；该账号会被锁定约 1 分钟。"
if confirm "执行 11 次错误登录？"; then
  last=""
  for _ in $(seq 1 11); do
    last=$(curl -s -o /dev/null -w '%{http_code}' -X POST --max-time 10 \
      -H 'Content-Type: application/json' \
      -d "{\"phone\":\"$TEST_PHONE\",\"password\":\"wrong-password\"}" \
      "$WEB/api/v1/c/auth/login" 2>/dev/null || true)
  done
  if [[ "$last" == "429" ]]; then
    say "  ${GREEN}✓${RESET} 第 11 次登录返回 429"; record "§6.9 登录限流" "PASS"
  else
    warn "第 11 次登录返回 ${last:-无响应}，期望 429"; record "§6.9 登录限流" "FAIL"
  fi
fi
warn "短信 6 次/分会发真实短信，向导不自动执行；请用专用号码手工验证并记录。"
if command -v gitleaks >/dev/null 2>&1; then
  if gitleaks detect --no-banner --redact --source . >/dev/null 2>&1; then
    say "  ${GREEN}✓${RESET} gitleaks 无命中"; record "§6.10 gitleaks" "PASS"
  else
    warn "gitleaks 有命中或执行失败"; record "§6.10 gitleaks" "FAIL"
  fi
else
  warn "未安装 gitleaks，需手工执行"; record "§6.10 gitleaks" "SKIP"
fi
say "生产日志敏感信息抽查："
note "ssh $ECS_SSH \"grep -Eai 'phone=|openid|password|token|authorization' /opt/yunhefc/logs/yunhefc.log | head -n 20\""
if confirm "日志无明文 phone/token/password/openid/Authorization？"; then
  record "§6.10 日志脱敏" "PASS"
else
  record "§6.10 日志脱敏" "FAIL"
fi
env_perm=$(ssh "${SSH_OPTS[@]}" "$ECS_SSH" "stat -c '%a' /opt/yunhefc/.env" 2>/dev/null || true)
if [[ "$env_perm" == "600" ]]; then
  say "  ${GREEN}✓${RESET} 生产 .env 权限 600"; record "§6.10 .env 权限" "PASS"
else
  warn ".env 权限为 ${env_perm:-未知}，期望 600"; record "§6.10 .env 权限" "FAIL"
fi
if confirm "生产未执行 test-data.sql，且首位管理员已改密？"; then
  record "§6.10 种子与管理员口令" "PASS"
else
  record "§6.10 种子与管理员口令" "FAIL"
fi

# ── Stage 10 ──────────────────────────────────────────────────────────────
